  assert.deepEqual(f.titles(), ['Third']);
  assert.equal(f.completion.value, 'Completed');
  assert.equal(f.priority.value, 'High');
  form = f.rows()[0].children[4];
  assert.equal(form.children[1].value, '2024-02-29');
